<?php
namespace App\Entity;
use Doctrine\Common\Collections\ArrayCollection; use Doctrine\Common\Collections\Collection; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] class Tour { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne(inversedBy:'tours')] #[ORM\JoinColumn(nullable:false)] private ?Course $course=null; #[ORM\Column] private int $numeroTour=0; #[ORM\Column(type:'float',nullable:true)] private ?float $temps=null; #[ORM\OneToMany(mappedBy:'tour',targetEntity:TourPilote::class)] private Collection $pilotes; public function __construct(){$this->pilotes=new ArrayCollection();} public function getId():?int{return $this->id;} public function getCourse():?Course{return $this->course;} public function setCourse(?Course $v):self{$this->course=$v;return $this;} public function getNumeroTour():int{return $this->numeroTour;} public function setNumeroTour(int $v):self{$this->numeroTour=$v;return $this;} public function getTemps():?float{return $this->temps;} public function setTemps(?float $v):self{$this->temps=$v;return $this;} public function getPilotes():Collection{return $this->pilotes;} }
